/*==============================================================================
IMAGE — Final Renderer (Edges always visible, faces with solid opacity)
==============================================================================*/

#define MAX_STEPS 80
#define USE_SUPERSAMPLING 1
#define SAMPLE_COUNT 4

// Disable size band-pass gating by default (set to 1 to re-enable)
#define USE_SIZE_BAND 1
const float RATIO_MAX = 2.0;  // only used if USE_SIZE_BAND==1
const float S_MIN  = 0.15;
const float S_MAX  = 0.65;
const float S_SOFT = 0.2;

// --- Local helpers (surface proxy & edges) ---
ivec4 getVoxelData(vec3 p){
    ivec3 c = ivec3(floor((p/(CUBE_SIZE*2.)+.5)*float(VOXEL_DIM)));
    return ivec4(texelFetch(iChannel1, to2D(clamp(c,0,VOXEL_DIM-1)), 0));
}
float hash12(vec2 p){ vec3 p3=fract(vec3(p.xyx)*.1031); p3+=dot(p3,p3.yzx+33.33); return fract((p3.x+p3.y)*p3.z); }
float map(vec3 p,vec3 p1,vec3 p2,vec3 p3,vec3 p4){
    float s=CUBE_SIZE*2.;
    float d12=.5*(boundaryDist(p,p1,s)-boundaryDist(p,p2,s));
    float d13=.5*(boundaryDist(p,p1,s)-boundaryDist(p,p3,s));
    float d14=.5*(boundaryDist(p,p1,s)-boundaryDist(p,p4,s));
    return max(d12,max(d13,d14));
}
float getEdgeWeight(vec3 p,vec3 p1,vec3 p2,vec3 p3,vec3 p4){
    float s=CUBE_SIZE*2.;
    float d1=boundaryDist(p,p1,s), d2=boundaryDist(p,p2,s);
    float d3=boundaryDist(p,p3,s), d4=boundaryDist(p,p4,s);
    float diff12=abs(d1-d2), diff13=abs(d1-d3);
    float edge12_13=(1.-smoothstep(.003,EDGE_THICKNESS,diff12))*(1.-smoothstep(.003,EDGE_THICKNESS,diff13));
    float edge12_14=(1.-smoothstep(.003,EDGE_THICKNESS,diff12))*(1.-smoothstep(.003,EDGE_THICKNESS,abs(d1-d4)));
    float edge13_14=(1.-smoothstep(.003,EDGE_THICKNESS,diff13))*(1.-smoothstep(.003,EDGE_THICKNESS,abs(d1-d4)));
    return max(max(edge12_13,edge12_14),edge13_14);
}
vec3 getNormal(vec3 p,vec3 p1,vec3 p2,vec3 p3,vec3 p4){
    vec2 e=vec2(EDGE_SHARPNESS*.1,0);
    return normalize(vec3(
        map(p+e.xyy,p1,p2,p3,p4)-map(p-e.xyy,p1,p2,p3,p4),
        map(p+e.yxy,p1,p2,p3,p4)-map(p-e.yxy,p1,p2,p3,p4),
        map(p+e.yyx,p1,p2,p3,p4)-map(p-e.yyx,p1,p2,p3,p4)
    ));
}

vec3 raymarch(vec2 fragCoord, vec2 jitter){
    vec3 backgroundColor = vec3(0.051,0.047,0.055);
    float ditherThreshold = bayer4x4(fragCoord + jitter);

    // Camera
    float angleH=iTime*AUTO_ROTATE_SPEED, angleV=0.;
    if(iMouse.z>0.){ angleH=(iMouse.x/iResolution.x-.5)*6.28318;
                     angleV=(iMouse.y/iResolution.y-.5)*3.14159;
                     angleV=clamp(angleV,-1.4,1.4); }
    float sh=sin(angleH), ch=cos(angleH);
    float sv=sin(angleV), cv=cos(angleV);
    mat3 rotY=mat3(ch,0,-sh, 0,1,0, sh,0,ch);
    mat3 rotX=mat3(1,0,0, 0,cv,sv, 0,-sv,cv);
    mat3 rot = rotX*rotY;

    vec3 ro=transpose(rot)*vec3(0.,0.,2.5);
    vec2 uv=(fragCoord+jitter-.5*iResolution.xy)/iResolution.y;
    vec3 rd=transpose(rot)*normalize(vec3(uv,-1.5));

    // Box intersection
    vec3 tMin=(vec3(-CUBE_SIZE)-ro)/rd, tMax=(vec3(CUBE_SIZE)-ro)/rd;
    vec3 t1=min(tMin,tMax), t2=max(tMin,tMax);
    float tNear=max(max(t1.x,t1.y),t1.z), tFar=min(min(t2.x,t2.y),t2.z);
    if(tNear>tFar||tFar<0.) return backgroundColor;

    float t=max(0.,tNear);
    for(int i=0;i<MAX_STEPS;i++){
        vec3 p=ro+rd*t;
        ivec4 nIds=getVoxelData(p); int id1=nIds.x;
        if(id1<0||nIds.y<0||nIds.z<0||nIds.w<0){ t+=.1; if(t>tFar)break; continue; }

        vec4 sS=getSiteData(iChannel0,id1);
        vec3 p1=sS.xyz, p2=getSiteData(iChannel0,nIds.y).xyz;
        vec3 p3=getSiteData(iChannel0,nIds.z).xyz, p4=getSiteData(iChannel0,nIds.w).xyz;

        float dist=map(p,p1,p2,p3,p4);
        if(dist<EDGE_SHARPNESS*.1){
            float radius=sS.w;

            // Controller aspect (for optional coloring)
            vec4 dS = texelFetch(iChannel2, siteUV(id1), 0);
            float payload = floor(dS.w*65535.0 + 0.5);
            float high8   = floor(payload/256.0);
            float norm_aspect = high8/255.0;
            float smoothed_aspect = norm_aspect*(ASPECT_MAX-1.0)+1.0;

            // Color selection
            vec3 baseColor;
            #if COLOR_SOURCE == SOURCE_DEBUG_CONTROLLER
                if (smoothed_aspect > TH_HI)      baseColor = vec3(0.000,0.431,1.000);
                else if (smoothed_aspect < TH_LO) baseColor = vec3(0.000,0.569,1.000);
                else                               baseColor = vec3(0.5);
            #elif COLOR_SOURCE == SOURCE_SOLID_COLOR
                baseColor = VIZ_SOLID_COLOR;
            #else
                float c_norm=clamp((smoothed_aspect-1.-VIZ_SKEW_MIN)/(VIZ_SKEW_MAX-VIZ_SKEW_MIN),0.,1.);
                baseColor = mix(vec3(0.1,0.2,0.8), vec3(1.0,0.3,0.1), c_norm);
            #endif

            // Face opacity (solid by default)
            float targetCellOpacity;
            #if OPACITY_SOURCE == SOURCE_SOLID_OPACITY
                targetCellOpacity = 1.0;
            #else
                float o_norm=0.;
                #if OPACITY_SOURCE == SOURCE_SIZE
                    o_norm=(radius-VIZ_SIZE_MIN)/(VIZ_SIZE_MAX-VIZ_SIZE_MIN);
                #elif OPACITY_SOURCE == SOURCE_SKEWNESS
                    o_norm=(smoothed_aspect-1.-VIZ_SKEW_MIN)/(VIZ_SKEW_MAX-VIZ_SKEW_MIN);
                #endif
                float curved_norm=pow(clamp(o_norm,0.,1.),VIZ_OPACITY_GAMMA);
                targetCellOpacity=mix(VIZ_OPACITY_AT_MIN,VIZ_OPACITY_AT_MAX,curved_norm);
            #endif

            // Optional size band-pass (disabled by default)
            #if USE_SIZE_BAND
                vec4 cS = texelFetch(iChannel3, siteUV(id1), 0);
                float norm_ratio = cS.r;
                float ratio      = norm_ratio * RATIO_MAX;
                float w_in   = smoothstep(S_MIN - S_SOFT, S_MIN + S_SOFT, ratio);
                float w_out  = smoothstep(S_MAX - S_SOFT, S_MAX + S_SOFT, ratio);
                float w_band = clamp(w_in*(1.0 - w_out), 0.0, 1.0);
                targetCellOpacity *= w_band;
            #endif

            // Edges always visible
            float edgeWeight = getEdgeWeight(p,p1,p2,p3,p4);
            float finalOpacity = mix(targetCellOpacity, 1.0, edgeWeight);
            if(finalOpacity<ditherThreshold){ t+=max(dist,.005); if(t>tFar)break; continue; }

            // Lighting
            vec3 n=transpose(rot)*getNormal(p,p1,p2,p3,p4);
            vec3 l=normalize(vec3(.8,.9,.6));
            float diff=max(0.,dot(n,l));
            vec3 v=normalize(-(ro+rd*t));
            float rim_factor=pow(1.-max(0.,dot(v,n)),2.)*VIZ_RIM_LIGHT_STRENGTH;
            vec3 rim=vec3(rim_factor);
            float lighting=diff*VIZ_DIFFUSE_STRENGTH+VIZ_AMBIENT_STRENGTH;

            vec3 cellColor=baseColor*lighting + rim;
            vec3 edgeColor=VIZ_EDGE_COLOR*lighting;
            vec3 surfaceColor=mix(cellColor, edgeColor, edgeWeight);
            float fog=smoothstep(tFar,tNear,t);
            return mix(backgroundColor,surfaceColor,fog);
        }

        t+=max(dist,.005);
        if(t>tFar) break;
    }
    return backgroundColor;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    #if USE_SUPERSAMPLING
        vec3 color=vec3(0.);
        for(int s=0;s<SAMPLE_COUNT;s++){
            vec2 o=vec2(hash12(fragCoord+float(s)*100.)-.5, hash12(fragCoord+float(s)*200.+13.)-.5)*.5;
            color+=raymarch(fragCoord,o);
        }
        fragColor=vec4(color/float(SAMPLE_COUNT),1.);
    #else
        fragColor=vec4(raymarch(fragCoord,vec2(0.)),1.);
    #endif
}

/*==============================================================================
BUFFER A — Site State (Position & Minimal Radius Controller)
Reads:
  iChannel1 (Buffer D).w = smoothed_aspect  (continuous float)
Writes:
  vec4(pos.xyz, R)
==============================================================================*/

vec3 hash33(vec3 p3){
    p3=fract(p3*vec3(.1031,.1030,.0973));
    p3+=dot(p3,p3.yxz+33.33);
    return -1.+2.*fract(vec3((p3.x+p3.y)*p3.z,(p3.x+p3.z)*p3.y,(p3.y+p3.z)*p3.x));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ivec2 p = ivec2(fragCoord);

    // Use only the SITE_ATLAS_W×SITE_ATLAS_H rectangle.
    if (p.x >= SITE_ATLAS_W || p.y >= SITE_ATLAS_H) { fragColor = vec4(0); return; }

    int siteId = p.y * SITE_ATLAS_W + p.x;
    if (siteId >= MAX_SITES) { fragColor = vec4(0); return; }

    // Bootstrap / previous state
    vec3 pos; float R;
    if (iFrame < 5) {
        pos = hash33(vec3(float(siteId),float(siteId)*.1,float(siteId)*.2))*CUBE_SIZE;
        R = INITIAL_RADIUS;
    } else {
        vec4 prevA = texelFetch(iChannel0, p, 0);
        pos = prevA.xyz; R = prevA.w;
    }

    // Physics from D
    vec4 phys = texelFetch(iChannel1, p, 0);
    vec3 vel  = (iFrame < 5) ? vec3(0.0) : phys.xyz;

    // --- DIRECT READ (continuous) ---
    float smoothed_aspect = phys.w;

    // -------- Minimal symmetric controller with deadband --------
    float R_prev   = R;
    float center   = 0.5 * (TH_HI + TH_LO);
    float halfBand = 0.5 * (TH_HI - TH_LO);
    float err      = smoothed_aspect - center;

    float u = 0.0;
    if (err >  halfBand) u = -CTRL_GAIN * (err - halfBand);        // shrink
    else if (err < -halfBand) u =  CTRL_GAIN * (-halfBand - err);  // grow

    float d = clamp(u, -CTRL_MAX_FRAC_STEP, CTRL_MAX_FRAC_STEP);    // rate limit
    R *= (1.0 + d);
    R = clamp(R, MIN_RADIUS, MAX_RADIUS);

    // Integrate position with periodic wrap
    pos += vel;
    pos = mod(pos + CUBE_SIZE, CUBE_SIZE*2.) - CUBE_SIZE;

    fragColor = vec4(pos, R);
}

/*==============================================================================
BUFFER B — 3D Voxel Field of Nearest Sites
(fixed 8×8 voxel atlas, safe OOB, periodic distance, seed-once + JFA refine)
==============================================================================*/

void updateClosest4(inout ivec4 ids, inout vec4 dists, vec3 p, int newId, sampler2D siteSampler)
{
    // ignore invalid and duplicates
    if (newId < 0 || newId == ids.x || newId == ids.y || newId == ids.z || newId == ids.w) return;

    // CRITICAL: periodic distance across ±CUBE_SIZE
    float d = boundaryDist(p, getSiteData(siteSampler, newId).xyz, CUBE_SIZE * 2.0);

    // insert into sorted top-4 (smallest first)
    if (d < dists.x) {
        dists = vec4(d, dists.xyz);
        ids   = ivec4(newId, ids.xyz);
    } else if (d < dists.y) {
        dists = vec4(dists.x, d, dists.yz);
        ids   = ivec4(ids.x, newId, ids.yz);
    } else if (d < dists.z) {
        dists = vec4(dists.xy, d, dists.w);
        ids   = ivec4(ids.xy, newId, ids.w);
    } else if (d < dists.w) {
        dists.w = d;
        ids.w   = newId;
    }
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // --- Fixed 64×64×64 grid packed as 8×8 slices → 512×512 atlas ---
    ivec2 atlasSize = ivec2(SLICES_PER_ROW * VOXEL_DIM,
                            VOXEL_DIM * (VOXEL_DIM / SLICES_PER_ROW));

    // SAFE OOB: write -1s (do NOT discard) so downstream ignores this texel
    if (any(greaterThanEqual(ivec2(fragCoord), atlasSize))) {
        fragColor = vec4(-1.0);
        return;
    }

    // Map to voxel + world position
    ivec3 v  = from2D(ivec2(fragCoord));
    vec3  p  = voxelToWorld(v);
    float L  = CUBE_SIZE * 2.0;

    // Update cadence: seed once; thereafter refine every N frames
    const int updateInterval = 10;
    bool doUpdate = (iFrame == 0) || (iFrame % updateInterval == 0);

    ivec4 bestIds   = ivec4(-1);
    vec4  bestDists = vec4(1e6);

    if (iFrame == 0) {
        // ---- Frame 0: one-time brute seed over all sites ----
        // (Relies on getSiteData() mapping from Common; no changes here.)
        for (int id = 0; id < MAX_SITES; ++id) {
            updateClosest4(bestIds, bestDists, p, id, iChannel0);
        }
    } else if (!doUpdate) {
        // ---- Not an update frame: reuse last frame as-is ----
        fragColor = texelFetch(iChannel1, ivec2(fragCoord), 0);
        return;
    } else {
        // ---- Update frame: start from last frame, re-eval, then JFA-refine ----
        bestIds = ivec4(texelFetch(iChannel1, ivec2(fragCoord), 0));
        // recompute current distances for the starting set
        for (int c = 0; c < 4; ++c) {
            int id = bestIds[c];
            bestDists[c] = (id >= 0) ? boundaryDist(p, getSiteData(iChannel0, id).xyz, L) : 1e6;
        }
    }

    // ---- Jump Flood–style refinement: 8 → 4 → 2 → 1 ----
    // Probe only neighbor voxels; test their 4 stored IDs (cheap & local).
    int steps[4] = int[4](8, 4, 2, 1);
    for (int pass = 0; pass < 4; ++pass) {
        int s = steps[pass];
        for (int dz = -1; dz <= 1; ++dz)
        for (int dy = -1; dy <= 1; ++dy)
        for (int dx = -1; dx <= 1; ++dx) {
            if (dx == 0 && dy == 0 && dz == 0) continue;

            ivec3 vn = v + ivec3(dx, dy, dz) * s;
            if (any(lessThan(vn, ivec3(0))) || any(greaterThanEqual(vn, ivec3(VOXEL_DIM)))) continue;

            ivec4 nIds = ivec4(texelFetch(iChannel1, to2D(vn), 0));
            // try each candidate (ignore negatives)
            updateClosest4(bestIds, bestDists, p, nIds.x, iChannel0);
            updateClosest4(bestIds, bestDists, p, nIds.y, iChannel0);
            updateClosest4(bestIds, bestDists, p, nIds.z, iChannel0);
            updateClosest4(bestIds, bestDists, p, nIds.w, iChannel0);
        }
    }

    fragColor = vec4(bestIds);
}

/*==============================================================================
COMMON — Shared Definitions & Minimal Controller
==============================================================================*/

// ===== Master Controls =====
#define MAX_SITES         60000
#define CUBE_SIZE         0.575
#define AUTO_ROTATE_SPEED 0.125

// ===== Physics (used by Buffer D) =====
#define STEERING_STRENGTH   0.05
#define REPULSION_STRENGTH  0.0015
#define TURBULENCE_STRENGTH 0.003
#define TURBULENCE_SCALE    2.5
#define FRICTION            0.15
#define MAX_SPEED           0.003
#define NEIGHBOR_COUNT      12

// ===== Minimal Radius Controller (used by Buffer A) =====
#define CTRL_GAIN           1.52   // one gain for both grow/shrink
#define CTRL_BAND           3.30   // dead-band width in aspect units
#define CTRL_MAX_FRAC_STEP  0.06   // max fractional radius change per frame
#define TH_LO (1.0 - 0.75*CTRL_BAND)
#define TH_HI (1.0 + 0.75*CTRL_BAND)
#define MIN_RADIUS        0.005
#define MAX_RADIUS        0.03
#define INITIAL_RADIUS    0.005
#define RADIUS_INFLATION  2.0      // coupling to neighbors (also used in C/D)
#define ASPECT_MAX        2.5      // decoding range for smoothed_aspect

// ===== Visualization =====
#define COLOR_SOURCE   SOURCE_SOLID_COLOR
#define OPACITY_SOURCE SOURCE_SOLID_OPACITY
#define VIZ_SOLID_COLOR vec3(0.169,0.000,1.000)
#define VIZ_EDGE_COLOR  vec3(0.000,0.482,1.000)
#define VIZ_DIFFUSE_STRENGTH   1.2
#define VIZ_AMBIENT_STRENGTH   0.25
#define VIZ_RIM_LIGHT_STRENGTH 0.2
#define VIZ_OPACITY_AT_MIN  1.0
#define VIZ_OPACITY_AT_MAX  0.0
#define VIZ_OPACITY_GAMMA   1.0
#define VIZ_SIZE_MIN      0.0001
#define VIZ_SIZE_MAX      0.005
#define VIZ_SKEW_MIN      0.0
#define VIZ_SKEW_MAX      1.5

// ===== System Internals / Enums =====
#define SOURCE_SOLID_COLOR  -2
#define SOURCE_SOLID_OPACITY -1
#define SOURCE_SKEWNESS      0
#define SOURCE_SPEED         1
#define SOURCE_DIRECTION     2
#define SOURCE_SIZE          3
#define SOURCE_DEBUG_CONTROLLER 4

// Site atlas layout (replaces %10,/10 addressing)
#define SITE_ATLAS_W 256
#define SITE_ATLAS_H ((MAX_SITES + SITE_ATLAS_W - 1) / SITE_ATLAS_W)
ivec2 siteUV(int id){ return ivec2(id % SITE_ATLAS_W, id / SITE_ATLAS_W); }

vec4 getSiteData(sampler2D s,int id){
    if(id<0 || id>=MAX_SITES) return vec4(1e6,1e6,1e6,-1.);
    return texelFetch(s, siteUV(id), 0);
}

// Voxel atlas
const int VOXEL_DIM = 64;
const int SLICES_PER_ROW = 8;

// Edge/AA
#define EDGE_SHARPNESS 0.0005
#define EDGE_THICKNESS 0.0032
#define DITHER_SCALE   5.0

// Periodic space
#define USE_PERIODIC_BOUNDARIES 1
const vec3 CUBE_VEC=vec3(CUBE_SIZE);
const vec3 CUBE_DIAMETER=vec3(2.*CUBE_SIZE);
vec3 periodic_diff(vec3 a,vec3 b){ vec3 d=a-b; return d-CUBE_DIAMETER*round(d/CUBE_DIAMETER); }
#if USE_PERIODIC_BOUNDARIES
vec3  boundaryDelta(vec3 a,vec3 b,float s){ return periodic_diff(a,b); }
float boundaryDist (vec3 a,vec3 b,float s){ return length(periodic_diff(a,b)); }
#else
vec3  boundaryDelta(vec3 a,vec3 b,float s){ return a-b; }
float boundaryDist (vec3 a,vec3 b,float s){ return length(a-b); }
#endif

// Noise & helpers
vec3 mod289(vec3 x){return x-floor(x*(1./289.))*289.;}
vec4 mod289(vec4 x){return x-floor(x*(1./289.))*289.;}
vec4 permute(vec4 x){return mod289(((x*34.)+1.)*x);}
vec4 taylorInvSqrt(vec4 r){return 1.79284291400159-.85373472095314*r;}
float snoise(vec3 v){
    const vec2 C=vec2(1./6.,1./3.); const vec4 D=vec4(0.,.5,1.,2.);
    vec3 i=floor(v+dot(v,C.yyy)); vec3 x0=v-i+dot(i,C.xxx);
    vec3 g=step(x0.yzx,x0.xyz); vec3 l=1.-g; vec3 i1=min(g.xyz,l.zxy); vec3 i2=max(g.xyz,l.zxy);
    vec3 x1=x0-i1+C.xxx; vec3 x2=x0-i2+C.yyy; vec3 x3=x0-D.yyy; i=mod289(i);
    vec4 p=permute(permute(permute(i.z+vec4(0.,i1.z,i2.z,1.))+i.y+vec4(0.,i1.y,i2.y,1.))+i.x+vec4(0.,i1.x,i2.x,1.));
    float n_=.142857142857; vec3 ns=n_*D.wyz-D.xzx; vec4 j=p-49.*floor(p*ns.z*ns.z);
    vec4 x_=floor(j*ns.z); vec4 y_=floor(j-7.*x_); vec4 x=x_*ns.x+ns.yyyy; vec4 y=y_*ns.x+ns.yyyy;
    vec4 h=1.-abs(x)-abs(y); vec4 b0=vec4(x.xy,y.xy); vec4 b1=vec4(x.zw,y.zw);
    vec4 s0=floor(b0)*2.+1.; vec4 s1=floor(b1)*2.+1.; vec4 sh=-step(h,vec4(0.));
    vec4 a0=b0.xzyw+s0.xzyw*sh.xxyy; vec4 a1=b1.xzyw+s1.xzyw*sh.zzww;
    vec3 p0=vec3(a0.xy,h.x); vec3 p1=vec3(a0.zw,h.y); vec3 p2=vec3(a1.xy,h.z); vec3 p3=vec3(a1.zw,h.w);
    vec4 norm=taylorInvSqrt(vec4(dot(p0,p0),dot(p1,p1),dot(p2,p2),dot(p3,p3)));
    p0*=norm.x; p1*=norm.y; p2*=norm.z; p3*=norm.w; vec4 m=max(.6-vec4(dot(x0,x0),dot(x1,x1),dot(x2,x2),dot(x3,x3)),0.); m=m*m;
    return 42.*dot(m*m,vec4(dot(p0,x0),dot(p1,x1),dot(p2,x2),dot(p3,x3)));
}
vec3 curlNoise(vec3 p){
    const float e=.1;
    float n1=snoise(vec3(p.x,p.y+e,p.z)), n2=snoise(vec3(p.x,p.y-e,p.z));
    float n3=snoise(vec3(p.x,p.y,p.z+e)), n4=snoise(vec3(p.x,p.y,p.z-e));
    float n5=snoise(vec3(p.x+e,p.y,p.z)), n6=snoise(vec3(p.x-e,p.y,p.z));
    float x=n2-n1-(n4-n3), y=n4-n3-(n6-n5), z=n6-n5-(n2-n1);
    return normalize(vec3(x,y,z));
}
vec3 hash31(int n){ uvec3 u=uvec3(n,n*16807,n*48271); u=u.yzx*u.zxy; u=u^(u>>16); return vec3(u)/float(0xffffffffU)*2.-1.; }

void getEigenSystem(mat3 M,out vec3 eigvals,out vec3 eigvec_min){
    float m=(M[0][0]+M[1][1]+M[2][2])/3.;
    M[0][0]-=m; M[1][1]-=m; M[2][2]-=m;
    float p=(M[0][0]*M[0][0]+M[1][1]*M[1][1]+M[2][2]*M[2][2]+2.*(M[0][1]*M[0][1]+M[0][2]*M[0][2]+M[1][2]*M[1][2]))/6.;
    float det=determinant(M); float r=det/(2.*pow(max(p,1e-9),1.5)); r=clamp(r,-1.,1.);
    float phi=acos(r)/3.; float p_sqrt=sqrt(p);
    eigvals.x=m+2.*p_sqrt*cos(phi);
    eigvals.y=m+2.*p_sqrt*cos(phi+2.09439510239);
    eigvals.z=m+2.*p_sqrt*cos(phi+4.18879020478);
    float l_min=min(eigvals.x,min(eigvals.y,eigvals.z));
    mat3 A=M; A[0][0]-=l_min; A[1][1]-=l_min; A[2][2]-=l_min;
    vec3 r0=vec3(A[0][0],A[0][1],A[0][2]);
    vec3 r1=vec3(A[1][0],A[1][1],A[1][2]);
    vec3 r2=vec3(A[2][0],A[2][1],A[2][2]);
    vec3 c01=cross(r0,r1), c12=cross(r1,r2), c20=cross(r2,r0), result_vec;
    if(dot(c01,c01)>dot(c12,c12)&&dot(c01,c01)>dot(c20,c20)) result_vec=c01;
    else if(dot(c12,c12)>dot(c20,c20)) result_vec=c12; else result_vec=c20;
    eigvec_min = (dot(result_vec,result_vec)<1e-12) ? vec3(0.) : normalize(result_vec);
}

// Voxel layout helpers
ivec3 from2D(ivec2 t){
    int sX=t.x/VOXEL_DIM; int sY=t.y/VOXEL_DIM; int z=sY*SLICES_PER_ROW+sX;
    return ivec3(t.x%VOXEL_DIM, t.y%VOXEL_DIM, z);
}
ivec2 to2D(ivec3 c){
    int sX=c.z%SLICES_PER_ROW; int sY=c.z/SLICES_PER_ROW;
    return ivec2(sX*VOXEL_DIM + c.x, sY*VOXEL_DIM + c.y);
}
vec3 voxelToWorld(ivec3 c){
    return (vec3(c)+.5)/float(VOXEL_DIM)*2.*CUBE_SIZE - CUBE_SIZE;
}
float bayer4x4(vec2 p){
    const mat4 b=mat4(0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5)/16.;
    ivec2 i=ivec2(mod(p*DITHER_SCALE,4.)); return b[i.x][i.y];
}

/*==============================================================================
BUFFER D — Shape Analysis & Physics (continuous aspect)
Writes:
  fragColor = vec4(vel.xyz, smoothed_aspect);   // .w is a continuous float
==============================================================================*/

const float ASPECT_ALPHA = 0.08;  // EMA smoothing for aspect signal

ivec3 wrapVoxelD(ivec3 v){
    return ivec3( ((v.x%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM,
                  ((v.y%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM,
                  ((v.z%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ivec2 p = ivec2(fragCoord);
    if (p.x >= SITE_ATLAS_W || p.y >= SITE_ATLAS_H) { fragColor = vec4(0.0); return; }
    int siteId = p.y * SITE_ATLAS_W + p.x;
    if (siteId >= MAX_SITES) { fragColor = vec4(0.0); return; }

    // Previous D (for vel and aspect smoothing)
    vec4 prevD = texelFetch(iChannel0, p, 0);
    vec3 vel   = (iFrame < 5) ? vec3(0.0) : prevD.xyz;

    // Previous smoothed aspect is directly in .w now (no packing)
    float prev_aspect = (iFrame < 5) ? 1.0 : prevD.w;

    // Self state
    vec4 selfA = texelFetch(iChannel1, p, 0);
    vec3 pos   = selfA.xyz;
    float Ra   = selfA.w;
    float space = CUBE_SIZE * 2.0;

    // Gather neighbors from B around our voxel (periodic 3x3x3)
    ivec3 center = ivec3(floor((pos/space + .5) * float(VOXEL_DIM)));
    int   nIDs[NEIGHBOR_COUNT];   for(int i=0;i<NEIGHBOR_COUNT;i++) nIDs[i]  = -1;
    float nDists[NEIGHBOR_COUNT]; for(int i=0;i<NEIGHBOR_COUNT;i++) nDists[i]= 1e6;
    vec3  nPos [NEIGHBOR_COUNT];

    for (int z=-1; z<=1; z++)
    for (int y=-1; y<=1; y++)
    for (int x=-1; x<=1; x++) {
        ivec3 nc = wrapVoxelD(center + ivec3(x,y,z));
        ivec4 ids = ivec4(texelFetch(iChannel2, to2D(nc), 0));
        int cand[4]; cand[0]=ids.x; cand[1]=ids.y; cand[2]=ids.z; cand[3]=ids.w;
        for (int j=0;j<4;j++) {
            int nid=cand[j]; if (nid<0 || nid==siteId) continue;
            vec3 q = getSiteData(iChannel1, nid).xyz;
            float d = boundaryDist(pos, q, space);
            if (d < nDists[NEIGHBOR_COUNT-1]) {
                nDists[NEIGHBOR_COUNT-1]=d; nIDs[NEIGHBOR_COUNT-1]=nid; nPos[NEIGHBOR_COUNT-1]=q;
                for (int k=NEIGHBOR_COUNT-2; k>=0; --k) {
                    if (nDists[k+1] < nDists[k]) {
                        float td=nDists[k]; nDists[k]=nDists[k+1]; nDists[k+1]=td;
                        int   ti=nIDs[k];   nIDs[k]=nIDs[k+1];     nIDs[k+1]=ti;
                        vec3  tp=nPos[k];   nPos[k]=nPos[k+1];     nPos[k+1]=tp;
                    } else break;
                }
            }
        }
    }

    // PCA → aspect (skewness) & shortest-axis direction (dirMin)
    int M = 0; for (int i=0;i<NEIGHBOR_COUNT;i++) if (nIDs[i]>=0) M++;
    float aspect = 1.0;
    vec3  dirMin = vec3(0.0);

    if (M > 3) {
        mat3 cov = mat3(0.0);
        for (int i=0;i<M;i++) {
            vec3 d = boundaryDelta(nPos[i], pos, space);
            cov[0][0]+=d.x*d.x; cov[0][1]+=d.x*d.y; cov[0][2]+=d.x*d.z;
            cov[1][1]+=d.y*d.y; cov[1][2]+=d.y*d.z;
            cov[2][2]+=d.z*d.z;
        }
        cov[1][0]=cov[0][1]; cov[2][0]=cov[0][2]; cov[2][1]=cov[1][2];
        vec3 eigvals; getEigenSystem(cov, eigvals, dirMin);
        float lmax=max(eigvals.x, max(eigvals.y, eigvals.z));
        float lmin=min(eigvals.x, min(eigvals.y, eigvals.z));
        if (lmin > 1e-7) aspect = sqrt(lmax/lmin);
    }

    // Repulsion & turbulence
    vec3 rep = vec3(0.0);
    for (int i=0;i<M;i++) {
        float Rb = getSiteData(iChannel1, nIDs[i]).w;
        float ideal = (Ra + Rb) * RADIUS_INFLATION;
        float d = nDists[i];
        if (d > 1e-6 && d < ideal) {
            float overlap = ideal - d;
            vec3 dir = boundaryDelta(pos, nPos[i], space) / d;
            rep += dir * overlap * REPULSION_STRENGTH;
        }
    }
    vec3 turb = curlNoise(pos * TURBULENCE_SCALE) * TURBULENCE_STRENGTH;

    // Integrate velocity
    vel += rep + turb;
    vel *= (1.0 - FRICTION);
    float L = length(vel);
    if (L > MAX_SPEED) vel *= (MAX_SPEED / max(L, 1e-9));

    // Smooth aspect (continuous, no quantization)
    float smoothed_aspect = mix(prev_aspect, aspect, ASPECT_ALPHA);

    // Output: .w is continuous smoothed_aspect
    fragColor = vec4(vel, smoothed_aspect);
}

/*==============================================================================
BUFFER C — Size/Spacing Metric for Viz
Inputs:
  iChannel0 = Buffer A (pos.xyz, R)
  iChannel1 = Buffer B (4 nearest IDs per voxel)
Output:
  .r = norm_ratio = clamp( spacingRatio / RATIO_MAX, 0..1 )
==============================================================================*/

const float RATIO_MAX = 2.0; // keep in sync with Image/D if you use band-pass

ivec3 wrapVoxelC(ivec3 v){
    return ivec3( ( (v.x%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM,
                  ( (v.y%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM,
                  ( (v.z%VOXEL_DIM)+VOXEL_DIM)%VOXEL_DIM );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ivec2 p = ivec2(fragCoord);
    if (p.x >= SITE_ATLAS_W || p.y >= SITE_ATLAS_H) { fragColor = vec4(0.0); return; }
    int siteId = p.y * SITE_ATLAS_W + p.x;
    if (siteId >= MAX_SITES) { fragColor = vec4(0.0); return; }

    vec4 selfA = texelFetch(iChannel0, p, 0);
    vec3 pos   = selfA.xyz;
    float Ra   = selfA.w;
    float space = CUBE_SIZE * 2.0;

    ivec3 center = ivec3(floor((pos/space + .5) * float(VOXEL_DIM)));

    int   nIDs[NEIGHBOR_COUNT];   for (int i=0;i<NEIGHBOR_COUNT;i++) nIDs[i]  = -1;
    float nDists[NEIGHBOR_COUNT]; for (int i=0;i<NEIGHBOR_COUNT;i++) nDists[i]= 1e6;

    // Pull candidates from 3x3x3 voxels (periodic)
    for (int z=-1; z<=1; z++)
    for (int y=-1; y<=1; y++)
    for (int x=-1; x<=1; x++) {
        ivec3 nc = wrapVoxelC(center + ivec3(x,y,z));
        ivec4 ids = ivec4(texelFetch(iChannel1, to2D(nc), 0));
        for (int j=0; j<4; j++) {
            int nid = (j==0)?ids.x : (j==1)?ids.y : (j==2)?ids.z : ids.w;
            if (nid < 0 || nid == siteId) continue;
            vec3 nPos = getSiteData(iChannel0, nid).xyz;
            float d = boundaryDist(pos, nPos, space);
            if (d < nDists[NEIGHBOR_COUNT-1]) {
                nDists[NEIGHBOR_COUNT-1] = d; nIDs[NEIGHBOR_COUNT-1] = nid;
                for (int k=NEIGHBOR_COUNT-2; k>=0; --k) {
                    if (nDists[k+1] < nDists[k]) {
                        float td=nDists[k]; nDists[k]=nDists[k+1]; nDists[k+1]=td;
                        int   ti=nIDs[k];   nIDs[k]=nIDs[k+1];     nIDs[k+1]=ti;
                    } else break;
                }
            }
        }
    }

    int M = 0;
    float avgN = 0.0, avgI = 0.0;
    for (int i=0;i<NEIGHBOR_COUNT;i++) {
        int nid = nIDs[i]; if (nid < 0) break;
        M++;
        float Rb = getSiteData(iChannel0, nid).w;
        avgN += nDists[i];
        avgI += (Ra + Rb) * RADIUS_INFLATION;
    }
    float spacingRatio = 1.0;
    if (M > 0 && avgI > 1e-6) { avgN /= float(M); avgI /= float(M); spacingRatio = avgN / avgI; }

    float norm_ratio = clamp(spacingRatio / RATIO_MAX, 0.0, 1.0);
    fragColor = vec4(norm_ratio, 0.0, 0.0, 1.0);
}
